		ctx = templ.InitializeContext(ctx)
		templ_7745c5c3_Var7 := templ.GetChildren(ctx)
		if templ_7745c5c3_Var7 == nil {
			templ_7745c5c3_Var7 = templ.NopComponent
		}
		ctx = templ.ClearChildren(ctx)
		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 7, "<section id=\"tafs\"><h2>3A. tafs</h2><p>tafs-এ আপনি একটি কাজ (যেমন ফেরত, বিল পরিশোধ বা কার্ড বিরোধ) একটি taf-কে দেন: একটি AI এজেন্ট যা আপনার সংযুক্ত টুল দিয়ে সময়সূচি অনুযায়ী কাজ করে, তার জন্য আপনার দেওয়া KIFF Card-এর মধ্যে। প্রতিটি taf আমাদের এজেন্ট runtime-এ চলে, এবং Anthropic তার ব্যবহৃত AI মডেল দেয়। আপনি tafs অ্যাপে তার আটকে রাখা কলের উত্তর দেন।</p><p><strong>আপনার টুল সংযোগ।</strong> Setup, tafs-এ একটি AI এজেন্ট যা taf-এর মতো চলে, টুল সংযোগ ও কাজের জন্য taf সাজাতে সাহায্য করে। এটি নিজে কিছু সংযোগ করে না। আপনি টুলের নিজস্ব প্রদানকারীর কাছে সাইন ইন করেন (যেমন Stripe), এবং আপনার ডিভাইসে প্রতিটি সংযোগ, taf যে টুল ব্যবহার করতে পারে এবং তার Card অনুমোদন করেন। সেই সাইন-ইনের token রাখে planque, আমাদের সংযোগ সেবা। এটি এনক্রিপ্টেড, শুধু KIFF-এর সিদ্ধান্ত নেওয়া কল করতে ব্যবহৃত এবং কখনো taf-কে দেওয়া হয় না। একটি টুল বিচ্ছিন্ন করলে প্রদানকারীর কাছে token প্রত্যাহার ও মুছে ফেলা হয়।</p><p><strong>আপনার Card-ই আপনার নির্দেশ।</strong> একটি taf আপনার টুলে পৌঁছায় শুধু KIFF-এর মাধ্যমে, যা পাঠানোর আগে প্রতিটি কল taf-এর Card-এর বিপরীতে যাচাই করে। আপনার দেওয়া Card-এর মধ্যে একটি কল আপনার নির্দেশে করা হয়। Card-এর বাইরের একটি কল আটকে রাখা বা প্রত্যাখ্যান করা হয়, Card যেমন বলে। আটকে রাখা কল করা হয় শুধু আপনার অ্যাকাউন্ট যাঁকে আটকে রাখা কলের উত্তর দিতে দেয় তিনি অনুমোদন করার পর। tafs অ্যাপে উত্তরে তাঁদের ডিভাইসের একটি স্বাক্ষর থাকে যা KIFF যাচাই করে, এবং রসিদ সেই প্রমাণ রাখে। আপনার অ্যাকাউন্ট KIFF-এর নিজের মধ্যেও উত্তর দিতে পারে (ড্যাশবোর্ড, এর কমান্ড-লাইন টুল, বা সেখানে আপনার অনুমোদিত অনুমোদনকারী); রসিদ তখন নথিভুক্ত করে কে এবং কীভাবে উত্তর দিয়েছে।</p><p><strong>অর্থপ্রদান।</strong> কোনো taf যখন আপনার হয়ে কোনো সাইটের চেকআউটে, সেই সাইটে সংরক্ষিত কার্ড বা অন্য অর্থপ্রদান পদ্ধতিতে অর্থ প্রদান করে, তখন তা করে কেবল একটি Card-এর ভেতরে এবং আপনি ফোনে সেই অর্থপ্রদান অনুমোদন করার পরে। আপনার অনুমোদন আপনার পক্ষ থেকে কেবল সেই একটি অর্থপ্রদানকে অনুমতি দেয়। সাইটটি এবং তার অর্থপ্রদান সেবাদাতা তা প্রক্রিয়া করে। KIFF এবং planque কখনও আপনার অর্থ ধরে রাখে না, আপনার কার্ডের তথ্য কখনও সংরক্ষণ করে না, এবং taf কখনও কার্ড নম্বর টাইপ করে না।</p><p><strong>আপনার কাছে যা থাকে।</strong> আপনি প্রতিটি taf-এর কাজ ও Card বাছাই করেন, তার আটকে রাখা কলের উত্তর দেন, এবং আপনার সংযুক্ত টুল ও অ্যাকাউন্ট ব্যবহারের অধিকার আছে তা নিশ্চিত করেন। taf-এর প্রতিবেদন, বার্তা ও মেমরি নোট একটি AI মডেল লেখে এবং ভুল হতে পারে; ভরসা করার আগে যা গুরুত্বপূর্ণ তা যাচাই করুন।</p><p><strong>একটি taf থামানো।</strong> আপনি একটি taf বা সবগুলো থামাতে (halt), একটি taf বিরতিতে রাখতে, এর যেকোনো Card প্রত্যাহার করতে বা সরাতে পারেন। আপনি যে মুহূর্তে taf থামান বা Card প্রত্যাহার করেন, KIFF তার অধীনে আর কোনো নতুন কল অনুমোদন করে না। tafs অ্যাপ একটি taf-কে থামানো দেখায় শুধু KIFF ও planque দুজনেই থামানো নিশ্চিত করার পর; তখন থেকে planque তার কোনো কল পাঠায় না, KIFF একটু আগে যে কল অনুমোদন করেছিল সেটিও না। টুল প্রদানকারীর কাছে ইতিমধ্যে পাঠানো অনুরোধ তবু সম্পন্ন হতে পারে: আমরা নতুন কল থামাই, প্রদানকারী যা করেছে তা ফেরাতে পারি না। যে টুল planque ছাড়া নিজে KIFF-এর অনুমতি যাচাই করে, KIFF একটু আগে যে অনুমতি দিয়েছিল তা সর্বোচ্চ 90 সেকেন্ড পর্যন্ত তবু গ্রহণ করতে পারে। থামানো taf আবার চালাতে আপনার ডিভাইসে আপনার অনুমোদন লাগে, এবং থামানোর আগে আটকে রাখা বা সারিতে থাকা কিছু তার পরে চলে না।</p><p><strong>একটি taf সরানো</strong> তার সময়সূচি থামায় এবং তার রান, চ্যাট, মেমরি ও সে যে কী ব্যবহার করত তা মুছে ফেলে। এর আগেও, আপনার টুল taf-কে যা ফেরত দেয় তা রাখা হয় শুধু তার রান শেষ হওয়া পর্যন্ত (চ্যাট যা শুধু পড়েছে, এনক্রিপ্ট করে, তার পরবর্তী বার্তার জন্য: সর্বোচ্চ চার ঘণ্টা ব্যবহৃত, তারপর মুছে ফেলা), এবং তার রান ও চ্যাট 30 দিন। KIFF যা করেছে তার রসিদ রাখে।</p><p><strong>ইইউ AI আইন।</strong> tafs-এর জন্য Kiff Agents OÜ AI সিস্টেমের প্রদানকারী এবং আপনি এর ডিপ্লয়ার। একটি taf আপনার কোম্পানির বাইরের কাউকে যা লেখে তাতে যেন বলা থাকে যে একটি AI এজেন্ট লিখেছে, আমরা তা নিশ্চিত করি। আপনি tafs ব্যবহার করেন শুধু সে কাজের জন্য যা এটি দেয়, এবং AI আইন যা নিষিদ্ধ করে বা উচ্চ-ঝুঁকিপূর্ণ বলে শ্রেণিবদ্ধ করে এমন কোনো ব্যবহারের জন্য নয়, যেমন কারও চাকরি, ঋণ বা অপরিহার্য সেবায় প্রবেশ নিয়ে সিদ্ধান্ত। আপনার Card যে মানবিক অনুমোদন চায় তা আপনি রাখেন এবং যাঁরা আপনার জন্য tafs ব্যবহার করেন তাঁরা এর কাজ ও সীমা বোঝেন তা নিশ্চিত করেন।</p><p><strong>খরচ।</strong> tafs আপনার KIFF প্ল্যানের অংশ (§8): taf-এর প্রতিটি রান তার ব্যবহৃত AI-র জন্য ক্রেডিট ব্যবহার করে। Coach এবং taf সাজানো Coach-এর ন্যায্য ব্যবহারের মধ্যে অন্তর্ভুক্ত।</p></section>")
